#!/usr/bin/env python3
"""Build the AE reference fixture for bae-anim's comparison tests.

Inputs (both produced by workstream 15, see docs/interop/ae-anim-samples.md):
  - AE sample results: anim-samples.ae-<version>.json (bridges/ae/bae-anim-samples.jsx run in AE)
  - case definitions:  bridges/ae/samples/anim-cases.json (for rational frame rates,
    layer options and the "other" properties that AE does not echo back)

Optional extra results (same "bae-anim-samples" format, e.g. cases re-sampled with
tools/ae/aectl) are merged in with --extra; a case id in an extra file replaces the
one from the main file.

Output: a compact JSON fixture (numbers rounded to 12 significant digits).

  python3 make_ae_fixture.py RESULTS.json CASES.json OUT.json [--extra MORE.json ...]
"""

import argparse
import json


def r12(x):
    if isinstance(x, float):
        return float(f"{x:.12g}")
    if isinstance(x, list):
        return [r12(v) for v in x]
    if isinstance(x, dict):
        return {k: r12(v) for k, v in x.items()}
    return x


def merged(defaults, case, key):
    out = dict(defaults.get(key, {}))
    out.update(case.get(key, {}))
    return out


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("results")
    ap.add_argument("cases")
    ap.add_argument("out")
    ap.add_argument("--extra", action="append", default=[])
    a = ap.parse_args()

    res = json.load(open(a.results))
    cases = json.load(open(a.cases))
    by_id = {c["id"]: c for c in cases["cases"]}
    results = {r["id"]: r for r in res["results"]}
    hosts = [res["host"]]
    for path in a.extra:
        extra = json.load(open(path))
        hosts.append(extra["host"])
        for r in extra["results"]:
            results[r["id"]] = r

    out_cases = []
    for cid, c in by_id.items():
        r = results.get(cid)
        if r is None or r.get("error"):
            continue
        comp = merged(cases["defaults"], c, "comp")
        layer_in = merged(cases["defaults"], c, "layer")
        lr = r["layer"]
        entry = {
            "id": cid,
            "group": c["group"],
            "comp": {
                "width": comp["width"],
                "height": comp["height"],
                "frame_rate": comp["frame_rate"],
                "duration": comp["duration"],
            },
            "layer": {
                "start_time": lr["start_time"],
                "stretch": lr["stretch"],
                "in_point": lr["in_point"],
                "out_point": lr["out_point"],
                "three_d": lr["three_d"],
                "separate_position": bool(layer_in.get("separate_position")),
                "effects": layer_in.get("effects", []),
            },
            "property": r["property"]["path"],
            "value_type": r["property"]["value_type"],
            "spatial": r["property"]["spatial"],
            "attr": r12(r["attr"]),
            "times": r["times"],
            "pre": r12(r["pre_expression"]),
        }
        if "other" in c:
            entry["other"] = c["other"]
        if "post_expression" in r:
            entry["post"] = r12(r["post_expression"])
        if r.get("expression_error"):
            entry["expression_error"] = r["expression_error"]
        out_cases.append(entry)

    fixture = {
        "format": "bae-anim-ae-fixture",
        "format_version": 1,
        "note": "Generated by make_ae_fixture.py from workstream 15's AE samples; "
        "keyframe times are comp times (AE keyTime), values are AE valueAtTime results.",
        "hosts": hosts,
        "cases": out_cases,
    }
    with open(a.out, "w") as f:
        json.dump(fixture, f, separators=(",", ":"), ensure_ascii=False)
        f.write("\n")


if __name__ == "__main__":
    main()
